-- ----------------------------------------------------------
-- Câu lệnh kiểm tra nhanh sau khi import
-- ----------------------------------------------------------
SELECT t.id AS idTau, t.tenTau, COUNT(tt.id) AS soToa
FROM Tau t
JOIN ToaTau tt ON tt.idTau = t.id
GROUP BY t.id, t.tenTau
ORDER BY t.id;

SELECT ct.id AS idChuyenTau, ct.idTau, COUNT(DISTINCT tt.id) AS soToa, COUNT(gc.id) AS soGheChuyen
FROM ChuyenTau ct
JOIN GheChuyen gc ON gc.idChuyenTau = ct.id
JOIN GheNgoi gn ON gn.id = gc.idGhe
JOIN ToaTau tt ON tt.id = gn.idToa
GROUP BY ct.id, ct.idTau
ORDER BY ct.id;
